CREATE OR REPLACE FUNCTION public.validate_company_setup(_details jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; BEGIN IF jsonb_typeof(_details) IS DISTINCT FROM 'object' OR length(trim(coalesce(_details->>'company_name','')))<2 OR length(_details->>'company_name')>160 THEN RAISE EXCEPTION 'A company name is required'; END IF; IF _details ? 'modules' THEN PERFORM public.validate_company_modules(_details->'modules'); END IF; FOR k IN SELECT key FROM jsonb_object_keys(_details) AS keys(key) WHERE key<>'modules' LOOP IF k NOT IN ('company_name','email','telephone','address','website','employer_nic_number','tax_id','vat_number') OR jsonb_typeof(_details->k)<>'string' OR length(_details->>k)>500 THEN RAISE EXCEPTION 'Invalid company field'; END IF; END LOOP; IF coalesce(_details->>'website','')<>'' AND (_details->>'website') !~* '^https?://' THEN RAISE EXCEPTION 'Use an https website address'; END IF; END $$;